function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){function h(s){var x=0;for(var i=0;i<s.length;i++){x=((x<<5)-x+s.charCodeAt(i))|0;}return(x>>>0).toString(16);}var R=prng(seed*32452843+43);var ok=0,broken=0,missing=0;for(var i=0;i<10;i++){var ev='evidence-'+(i+1)+'-seed'+seed;var stored=h(ev);var r=R();var chk=r<0.7?stored:(r<0.85?'deadbeef':null);if(chk===null){missing++;}else if(chk===h(ev)){ok++;}else{broken++;}}return{claims:10,verified:ok,broken_links:broken,missing_evidence:missing,integrity_ok:broken===0&&missing===0};}
var SEED = 89501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

